const raw = $json;
const str = v => typeof v === 'string' ? v : '';
const emailOK = v => typeof v === 'string' && /^[^\s<>@]+@[^\s<>@]+\.[^\s<>@]+$/.test(v);
function address(value) {
 if (typeof value === 'string') {
  const m = value.match(/<([^<>]+)>/);
  return {email:(m ? m[1] : value).trim(), name:m ? value.slice(0,value.indexOf('<')).trim().replace(/^"|"$/g,'') : ''};
 }
 const first = value?.value?.[0] || value || {};
 return {email:str(first.address), name:str(first.name)};
}
const from = address(raw.from);
let senderName = from.name, senderEmail = from.email;
let subject = str(raw.subject), body = str(raw.textPlain) || str(raw.text);
let source = 'email';
const transportText = body || str(raw.textHtml) || str(raw.html);
const isFormspree = /@(?:[a-z0-9-]+\.)*formspree\.(?:io|com)$/i.test(from.email)
 || /Someone just submitted your form/i.test(transportText)
 || /JOIN_REQUEST_V1_BEGIN/.test(transportText);
if (isFormspree) {
 source = 'formspree';
 // Paired with stakeholder.js. This marker is formatting, not authentication.
 const matches = [...transportText.matchAll(/JOIN_REQUEST_V1_BEGIN([\s\S]*?)JOIN_REQUEST_V1_END/g)];
 if (matches.length !== 1) throw new Error('Formspree: eindeutige Nutzdaten fehlen. Neue stakeholder.js verwenden und neu senden. Kein Ticket angelegt.');
 let p;
 try { p = JSON.parse(decodeURIComponent(matches[0][1].replace(/\s/g,''))); }
 catch { throw new Error('Formspree-Nutzdaten beschädigt; kein Ticket angelegt.'); }
 if (!p || p.version !== 1 || typeof p.name !== 'string' || !p.name.trim()
   || typeof p.subject !== 'string' || typeof p.message !== 'string' || !emailOK(p.email)) {
   throw new Error('Formspree-Pflichtfelder ungültig; kein Ticket angelegt.');
 }
 senderName = p.name.trim(); senderEmail = p.email.trim(); subject = p.subject; body = p.message;
} else if (!body) {
 throw new Error('Keine Klartext-Nachricht vorhanden. HTML-only-Mail vor Verarbeitung in Klartext umwandeln.');
}
body = (s => {
 const pairs = [['\u00c3\u00a4','ä'],['\u00c3\u00b6','ö'],['\u00c3\u00bc','ü'],['\u00c3\u0084','Ä'],['\u00c3\u201e','Ä'],['\u00c3\u0096','Ö'],['\u00c3\u2013','Ö'],['\u00c3\u009c','Ü'],['\u00c3\u0153','Ü'],['\u00c3\u009f','ß'],['\u00c3\u0178','ß']];
 for (const [bad, good] of pairs) s = s.split(bad).join(good);
 return s;
})(body);
if (!emailOK(senderEmail) || !subject.trim() || !body.trim()) throw new Error('Absender, Betreff oder Nachricht fehlen; kein Ticket angelegt.');
if (body.length > 50000 || subject.length > 500) throw new Error('Nachricht zu lang; manuell prüfen.');
if (/\uFFFD/.test(body)) throw new Error('Nachricht enthält verlorene Zeichen (�); Originalmail prüfen.');
const parsedDate = new Date(raw.date);
const stamp = raw.date && Number.isFinite(parsedDate.getTime()) ? parsedDate : new Date();
const parts = new Intl.DateTimeFormat('en', {timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(stamp);
const part = type => parts.find(p=>p.type===type).value;
const referenceDate = `${part('year')}-${part('month')}-${part('day')}`;
return {json:{senderName,senderEmail,subject,body,source,referenceDate}};

const mail = $('Extract data').item.json;
let ai = $json.output;
if (typeof ai === 'string') {
  ai = JSON.parse(ai.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, ''));
}
if (!ai || typeof ai !== 'object' || Array.isArray(ai)) throw new Error('KI-Ausgabe fehlt oder ist kein Objekt.');
const clean = v => typeof v === 'string' && !['undefined','null'].includes(v.trim().toLowerCase()) ? v.trim().normalize('NFC') : '';

if (ai.isTask !== true) throw new Error('Keine konkrete Aufgabenanfrage erkannt; kein Ticket angelegt.');
if (!Array.isArray(ai.assigned) || !Array.isArray(ai.subtask)) throw new Error('KI-Listen fehlen; kein Ticket angelegt.');
if (typeof ai.deadline !== 'string' || !['Herr','Frau',''].includes(ai.salutation)) throw new Error('KI-Pflichtfelder ungültig.');
for (const a of ai.assigned) {
 if (!a || !clean(a.name) || typeof a.email !== 'string') throw new Error('Ungültige zuständige Person.');
 if (a.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(a.email)) throw new Error('Ungültige E-Mail einer zuständigen Person.');
}
for (const s of ai.subtask) {
 if (!s || !clean(s.value) || !Number.isInteger(s.id) || s.id < 0 || s.edit !== false || s.checked !== false) throw new Error('Ungültige Teilaufgabe.');
}

const title = mail.subject;
const body = typeof mail.body === 'string' ? mail.body : '';
if (!Array.isArray(ai.removeFromDescription)) throw new Error('KI-Ausgabe: removeFromDescription fehlt.');
const ranges = [];
for (const fragment of new Set(ai.removeFromDescription)) {
  if (typeof fragment !== 'string' || !fragment.trim()) throw new Error('Ungültiger Beschreibungsausschnitt.');
  const start = body.indexOf(fragment);
  if (start < 0 || body.indexOf(fragment, start + 1) >= 0) {
    throw new Error('KI-Ausschnitt nicht eindeutig im Originaltext gefunden. Ausgabe prüfen; kein Ticket angelegt.');
  }
  ranges.push({start, end: start + fragment.length});
}
ranges.sort((a,b) => a.start - b.start);
let cursor = 0;
let description = '';
for (const range of ranges) {
  if (range.start < cursor) throw new Error('Überlappende KI-Ausschnitte; kein Ticket angelegt.');
  description += body.slice(cursor, range.start);
  cursor = range.end;
}
description += body.slice(cursor);
description = description.trim();
if (!description) throw new Error('Beschreibung nach Verarbeitung leer; kein Ticket angelegt.');
if (typeof title !== 'string' || !title.trim()) throw new Error('E-Mail-Betreff fehlt.');
if (!body.trim()) throw new Error('E-Mail-Text fehlt.');
if (!['User Story','Technical Task'].includes(ai.category)) throw new Error('Ungültige Kategorie.');
if (!['urgent','medium','low'].includes(ai.priority)) throw new Error('Ungültige Priorität.');
let date = clean(ai.deadline) || mail.referenceDate;
const de = /^(\d{1,2})\.(\d{1,2})\.(\d{4})$/.exec(date);
if (de) date = `${de[3]}-${de[2].padStart(2,'0')}-${de[1].padStart(2,'0')}`;
if (date) {
  const d = new Date(`${date}T00:00:00Z`);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !Number.isFinite(d.getTime()) || d.toISOString().slice(0,10) !== date) {
    throw new Error('Ungültige KI-Frist: ' + date);
  }
}
const seen = new Set();
const assigned = (Array.isArray(ai.assigned) ? ai.assigned : []).filter(a => a && clean(a.name)).map(a => {
  const name = clean(a.name);
  const candidate = clean(a.email);
  const email = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(candidate) ? candidate : '';
  return {name, email, avatar: name.split(/\s+/).map(x => Array.from(x)[0]).slice(0,2).join('').toUpperCase(), color:'#4589FF', assigned:true};
}).filter(a => {
  const key = (a.email || a.name).toLowerCase();
  if (seen.has(key)) return false;
  seen.add(key); return true;
});
const subtask = (Array.isArray(ai.subtask) ? ai.subtask : []).filter(s => s && clean(s.value)).map((s,id) => ({id, value:clean(s.value), edit:false, checked:false}));
return {
  json: {
    title,
    description,
    category: ai.category,
    priority: ai.priority,
    date,
    status: 'triage',
    order: 0,
    creatorName: clean(mail.senderName) || clean(mail.senderEmail),
    creatorType: 'external',
    aiGenerated: true,
    salutation: ['Herr', 'Frau'].includes(ai.salutation)
      ? ai.salutation
      : '',
    assigned,
    subtask
  }
};

const state = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
const limit = 10;
if (state.requestDate !== today) {
  state.requestDate = today;
  state.requestCount = 0;
}
const count = Number(state.requestCount);
state.requestCount = (Number.isSafeInteger(count) && count >= 0 ? count : 0) + 1;
return {
  json: {
    ...$json,
    dailyRequestCount: state.requestCount,
    dailyRequestLimit: limit,
    limitReached: state.requestCount > limit
  }
};

