parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "description": "Genau 'User Story' für Feature-Wünsche/Verbesserungen aus Nutzersicht, oder 'Technical Task' für technische Aufgaben/Bugs/Code-Änderungen.",
      "enum": [
        "User Story",
        "Technical Task"
      ]
    },
    "priority": {
      "type": "string",
      "description": "'urgent' bei Wörtern wie dringend/asap/kritisch, sonst 'medium' oder 'low' je nach Tonfall.",
      "enum": [
        "urgent",
        "medium",
        "low"
      ]
    },
    "deadline": {
      "type": "string",
      "description": "Explizite Frist als YYYY-MM-DD. Relative Angaben anhand des Referenzdatums auflösen. Ohne eindeutige Frist leerer String. Keine Frist erfinden."
    },
    "salutation": {
      "type": "string",
      "description": "Nur explizit bekannte Anrede des Absenders, sonst leerer String. Nicht anhand des Namens raten.",
      "enum": [
        "Herr",
        "Frau",
        ""
      ]
    },
    "subtask": {
      "type": "array",
      "description": "Nur explizit genannte Teilaufgaben übernehmen, möglichst im Originalwortlaut. Keine zusätzlichen Schritte erfinden. Ohne explizite Teilaufgaben [].",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "number"
          },
          "value": {
            "type": "string"
          },
          "edit": {
            "type": "boolean"
          },
          "checked": {
            "type": "boolean"
          }
        },
        "required": [
          "id",
          "value",
          "edit",
          "checked"
        ]
      }
    },
    "assigned": {
      "type": "array",
      "description": "Nur ausdrücklich zuständige Personen. Namen unverändert übernehmen. E-Mail nur falls explizit vorhanden, sonst leerer String. Keine Adressen erfinden. Sonst leeres Array.",
      "items": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string"
          },
          "email": {
            "type": "string"
          }
        },
        "required": [
          "name",
          "email"
        ]
      }
    },
    "removeFromDescription": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Exakte, zusammenhängende, jeweils eindeutig vorkommende Textausschnitte aus body, die zu entfernen sind: explizite Zuweisungsklauseln, Fristklauseln, separate Aufgabenlisten inkl. Einleitung, Signaturen und zitierte Altnachrichten. Keine freie Neufassung. Nicht überlappend. Sachliche Kernbeschreibung erhalten. Ohne solche Stellen []."
    },
    "isTask": {
      "type": "boolean",
      "description": "True nur bei einer konkreten Aufgabenanfrage. Reine Benachrichtigungen, Werbung, Autoantworten und inhaltslose Testnachrichten ohne Aufgabe: false."
    }
  },
  "required": [
    "category",
    "priority",
    "deadline",
    "salutation",
    "subtask",
    "assigned",
    "removeFromDescription",
    "isTask"
  ]
}
